import argparse
import sys
import time

from pathlib import Path


sys.path.insert(
    0,
    str(Path(__file__).resolve().parent.parent)
)

from src.llm import _get_client  # noqa: E402  (loads .env)


p = argparse.ArgumentParser()

p.add_argument(
    "--model",
    required=True
)

a = p.parse_args()


prompt = (
    "Summarise in three sentences: The regulation lays down harmonised rules on fair access "
    "to and use of data. It applies to manufacturers of connected products and providers of "
    "related services. Users have the right to access data generated by their use of a product."
)


for label, extra in [
    ("default", None),
    ("reasoning off", {"reasoning": {"enabled": False}})
]:

    args = {
        "model": a.model,
        "temperature": 0,
        "messages": [
            {
                "role": "user",
                "content": prompt
            }
        ]
    }

    if extra:
        args["extra_body"] = extra

    t0 = time.time()

    try:

        r = _get_client().chat.completions.create(**args)

        u = r.usage

        det = getattr(
            u,
            "completion_tokens_details",
            None
        )

        reasoning = (
            getattr(det, "reasoning_tokens", 0)
            if det
            else 0
        )

        prov = (
            getattr(r, "provider", None)
            or (r.model_extra or {}).get("provider", "?")
        )

        print(
            f"{label:14s} provider={prov}  "
            f"{time.time() - t0:5.1f}s  "
            f"completion={u.completion_tokens}  "
            f"reasoning={reasoning}"
        )

        print(
            "   ",
            (r.choices[0].message.content or "")
            .strip()[:200]
            .replace("\n", " ")
        )

    except Exception as e:  # noqa: BLE001

        print(
            f"{label:14s} ERROR: {str(e)[:200]}"
        )